ALTER TABLE "gift_payment_record" ADD COLUMN "provider_installment_reference" text;--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD COLUMN "installment_number" integer;--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD COLUMN "platform_adjustment_cents" integer;--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD COLUMN "platform_adjustment_dispatch_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD COLUMN "platform_adjustment_next_attempt_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD COLUMN "platform_adjustment_transfer_reference" text;--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD COLUMN "platform_adjustment_funded_at" timestamp with time zone;--> statement-breakpoint
CREATE INDEX "gift_payment_adjustment_pending_idx" ON "gift_payment_record" USING btree ("environment","platform_adjustment_next_attempt_at") WHERE "gift_payment_record"."platform_adjustment_cents" IS NOT NULL AND "gift_payment_record"."platform_adjustment_funded_at" IS NULL;--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD CONSTRAINT "gift_payment_installment_key" UNIQUE("site_id","account_id","environment","order_id","installment_number");--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD CONSTRAINT "gift_payment_adjustment_transfer_key" UNIQUE("environment","platform_adjustment_transfer_reference");--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD CONSTRAINT "gift_payment_installment_check" CHECK (("gift_payment_record"."provider_installment_reference" IS NULL AND "gift_payment_record"."installment_number" IS NULL) OR ("gift_payment_record"."provider_installment_reference" IS NOT NULL AND length("gift_payment_record"."provider_installment_reference") > 0 AND "gift_payment_record"."installment_number" IS NOT NULL AND "gift_payment_record"."installment_number" > 0));--> statement-breakpoint
ALTER TABLE "gift_payment_record" ADD CONSTRAINT "gift_payment_platform_adjustment_check" CHECK (("gift_payment_record"."platform_adjustment_cents" IS NULL AND num_nonnulls("gift_payment_record"."platform_adjustment_dispatch_at", "gift_payment_record"."platform_adjustment_next_attempt_at", "gift_payment_record"."platform_adjustment_transfer_reference", "gift_payment_record"."platform_adjustment_funded_at") = 0) OR ("gift_payment_record"."platform_adjustment_cents" IS NOT NULL AND "gift_payment_record"."platform_adjustment_cents" > 0 AND ("gift_payment_record"."platform_adjustment_transfer_reference" IS NULL OR "gift_payment_record"."platform_adjustment_dispatch_at" IS NOT NULL) AND ("gift_payment_record"."platform_adjustment_funded_at" IS NULL OR ("gift_payment_record"."platform_adjustment_transfer_reference" IS NOT NULL AND "gift_payment_record"."platform_adjustment_funded_at" >= "gift_payment_record"."platform_adjustment_dispatch_at"))));